const lead = $json.lead ?? {};
const slots = $json.availableSlots ?? [];
const preferred = `${lead.preferredInspectionWindow ?? ''}`.toLowerCase();
const matchedSlot = slots.find((slot) => preferred.includes('afternoon') && Number(`${slot.startsAt}`.slice(11, 13)) >= 12) ?? slots[0] ?? null;
return [{ json: { leadId: lead.leadId, homeownerName: lead.homeownerName, routing: matchedSlot ? 'slot-available' : 'dispatcher-callback', matchedSlot, nextAction: matchedSlot ? 'Offer inspection slot for office approval.' : 'Create dispatcher callback task.' } }];
